def is_triangle_free(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for i in range(n):
        for j in adj[i]:
            for k in adj[j]:
                if i in adj[k]:
                    return False
    return True

